<?php defined('BASEPATH') or exit('No direct script access allowed');$company_page_title='Faturamento de horas em lote';require APPPATH.'views/admin/includes/native_company_layout_head.php';$esc=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=CompanyRequestScope::adminUrl($this,'projects/time_billing');$hidden=function($action)use($esc,$company_time_billing_csrf,$request_key,$choices,$billing){foreach(['action'=>$action,'company_time_billing_csrf'=>$company_time_billing_csrf,'request_key'=>$request_key] as $k=>$v)echo '<input type="hidden" name="'.$esc($k).'" value="'.$esc($v).'">';if($choices)echo '<input type="hidden" name="project_id" value="'.(int)$choices['project']['id'].'"><input type="hidden" name="revision" value="'.(int)$choices['project']['revision'].'">';if($billing)echo '<input type="hidden" name="origin_id" value="'.(int)$billing['origin_id'].'">';}; ?>
<section class="company-settings-card"><h1>Faturamento de horas em lote</h1><p>Selecione timers encerrados inteiros. Uma reserva durável impede reutilizar as mesmas horas; cancelar a fatura não libera timers já utilizados. A emissão cria uma conta a receber, sem registrar caixa.</p><?php if($error){ ?><p role="alert"><?= $esc($error); ?></p><?php }if(!$choices){ ?><ul><?php foreach(($projects['items']??[]) as $p){ ?><li><a href="<?= $esc($url.'?project='.(int)$p['id']); ?>"><?= $esc($p['name'].' · '.$p['status']); ?></a></li><?php } ?></ul><?php if($projects['next']??null){ ?><a href="<?= $esc($url.'?after='.(int)$projects['next']); ?>">Próxima página</a><?php }}else{ ?><h2><?= $esc($choices['project']['name']); ?></h2>
<?php if($billing){$payload=$billing['payload'];$totals=CompanyInvoiceAmounts::calculate($payload['items'],array_intersect_key($payload,array_flip(['discount_mode','discount_value','discount_type','adjustment']))); ?><h3>Lote preservado #<?= (int)$billing['origin_id']; ?></h3><dl><dt>Estado do vínculo (histórico)</dt><dd id="time-billing-state"><?= $esc($billing['state']); ?></dd><dt>Valor original da declaração</dt><dd id="time-billing-total"><?= $esc($billing['currency'].' · '.$totals['total']); ?></dd></dl><table class="table"><thead><tr><th>Item</th><th>Horas</th><th>Taxa</th><th>Tributos</th></tr></thead><tbody><?php foreach($payload['items'] as $item){ ?><tr><td><?= $esc($item['description']); ?></td><td><?= $esc($item['qty']); ?></td><td><?= $esc($item['rate']); ?></td><td><?php foreach($item['taxes'] as $tax){ ?><?= $esc($tax['name'].' '.$tax['rate'].'%'); ?><br><?php } ?></td></tr><?php } ?></tbody></table><p>Timers selecionados, incluindo os que arredondam para zero: <?= $esc(implode(', ',$billing['source']['timer_ids'])); ?>. Intervalos, horas e valores seguem a declaração preservada. Em uma linha, durações por tarefa inferiores a 60 segundos não compõem a quantidade, conforme o formato nativo.</p><?php require APPPATH.'views/admin/includes/native_company_billing_invoice_current.php';if($billing['invoice_id']){ ?><a id="time-billing-invoice" href="<?= $esc(CompanyRequestScope::adminUrl($this,'invoices?invoice='.(int)$billing['invoice_id'])); ?>">Abrir fatura vinculada</a><?php }elseif(in_array($billing['state'],['ready','converting'],true)){ ?><?= form_open($url,['id'=>'time-billing-convert']);$hidden('convert'); ?><button id="time-billing-issue" type="submit"><?= $billing['state']==='converting'?'Retomar a mesma emissão':'Emitir fatura do lote revisado'; ?></button><?= form_close(); ?><?php }if($billing['state']==='ready'||($billing['can_release']??false)){ ?><?= form_open($url,['id'=>'time-billing-disable']);$hidden('disable'); ?><button type="submit">Retirar declaração sem recibo de fatura</button><?= form_close(); ?><?php }} ?>
<h3>Nova seleção de horas ainda disponíveis</h3><?= form_open($url,['id'=>'time-billing-prepare']);$hidden('prepare'); ?><label>Seleção<select id="time-billing-selection" name="billing[selection_mode]"><option value="selected_timers">Timers marcados</option><option value="selected_tasks">Todas as horas disponíveis das tarefas marcadas</option><?php if($choices['project']['status']==='completed'){ ?><option value="project_remaining">Projeto concluído inteiro: horas restantes</option><?php } ?></select></label><table class="table"><thead><tr><th>Timer</th><th>Tarefa</th><th>Início / fim</th><th>Segundos</th><th>Alocação</th></tr></thead><tbody><?php $taskNames=[];foreach($choices['timers'] as $timer){$taskNames[(int)$timer['task_id']]=$timer['name'];$available=$timer['stopped_at']!==null&&$timer['allocation_state']===null; ?><tr><td><label><?php if($available){ ?><input type="checkbox" name="billing[timer_ids][]" value="<?= (int)$timer['timer_id']; ?>"><?php } ?>#<?= (int)$timer['timer_id']; ?></label></td><td><?= $esc($timer['name']); ?></td><td><?= $esc($timer['started_at'].' / '.($timer['stopped_at']??'Em execução')); ?></td><td><?= $esc($timer['seconds']); ?></td><td><?= $esc($timer['allocation_state']??($available?'Disponível':'Em execução')); ?></td></tr><?php } ?></tbody></table><fieldset><legend>Tarefas para o formato de lote por tarefa</legend><?php foreach($taskNames as $id=>$name){ ?><label><input type="checkbox" name="billing[task_ids][]" value="<?= $id; ?>"><?= $esc($name); ?></label><?php } ?></fieldset>
<label>Preço<select id="time-billing-price-source" name="billing[rate_source]"><option value="explicit">Taxa única explícita</option><option value="per_task">Taxas explícitas por tarefa</option><?php if($rate){ ?><option value="project">Taxa preservada do projeto #<?= (int)$rate['id']; ?></option><?php } ?></select></label><?php if($rate){ ?><input type="hidden" name="billing[project_rate_id]" value="<?= (int)$rate['id']; ?>"><?php } ?><label>Taxa única por hora<input id="time-billing-rate" name="billing[rate]" inputmode="decimal"></label><label>Arredondamento<select name="billing[round_mode]"><option value="none">Sem intervalo</option><option value="up">Para cima</option><option value="down">Para baixo</option><option value="nearest">Mais próximo, empate para cima</option></select></label><label>Intervalo em minutos<select name="billing[round_minutes]"><?php foreach([0,5,10,15,20,25,30,35,40,45] as $m){ ?><option value="<?= $m; ?>"><?= $m; ?></option><?php } ?></select></label><fieldset><legend>Preço por tarefa (preencha todas as tarefas selecionadas nesse perfil)</legend><?php foreach($taskNames as $id=>$name){ ?><label><?= $esc($name); ?><input name="billing[prices][<?= $id; ?>][rate]" inputmode="decimal"></label><input type="hidden" name="billing[prices][<?= $id; ?>][round_mode]" value="none"><input type="hidden" name="billing[prices][<?= $id; ?>][round_minutes]" value="0"><?php } ?></fieldset><label>Formato<select id="time-billing-lines" name="billing[line_mode]"><option value="task_per_item">Um item por tarefa</option><option value="timesheets_individually">Um item por timer encerrado</option><option value="single_line">Uma linha para o projeto, mesma taxa</option></select></label><label>Moeda<select name="billing[currency]"><?php foreach($currencies as $cur){ ?><option value="<?= (int)$cur['id']; ?>"><?= $esc($cur['name']); ?></option><?php } ?></select></label><label>Data<input id="time-billing-date" type="date" name="billing[date]" value="<?= gmdate('Y-m-d'); ?>" required></label><label>Vencimento<input id="time-billing-due" type="date" name="billing[due_date]" value="<?= gmdate('Y-m-d'); ?>" required></label><fieldset><legend>Tributos (até10 por item)</legend><?php for($i=0;$i<10;$i++){ ?><label>Nome<input name="billing[taxes][<?= $i; ?>][name]"></label><label>Alíquota%<input name="billing[taxes][<?= $i; ?>][rate]" value="0.00"></label><?php } ?></fieldset><label>Desconto<select name="billing[discount_mode]"><option value="fixed">Valor fixo</option><option value="percent">Percentual</option></select></label><input name="billing[discount_value]" value="0.00"><select name="billing[discount_type]"><option value="after_tax">Após tributos</option><option value="before_tax">Antes dos tributos</option></select><label>Ajuste<input name="billing[adjustment]" value="0.00"></label><label>Nota<textarea name="billing[note]"></textarea></label><label><input id="time-billing-confirm" type="checkbox" name="billable" value="1" required> Conferi os timers inteiros, cliente do projeto, moeda, preços e valores.</label><button id="time-billing-review" type="submit">Preservar lote para revisão</button><?= form_close(); ?>
<?php if($choices['next']!==null){ ?><a id="time-billing-timers-next" href="<?= $esc($url.'?'.http_build_query(($billing?['origin'=>$billing['origin_id']]:['project'=>$choices['project']['id']])+['timer_after'=>$choices['next']])); ?>">Próxima página de timers</a><p>Os timers selecionados pertencem a esta página. A seleção por tarefa ou projeto considera todas as horas disponíveis desse recorte, respeitando a quota por declaração.</p><?php } ?><h3>Histórico de lotes do projeto</h3><p>Até100 lotes mais recentes. Para abrir um vínculo histórico pelo seu número, use a consulta abaixo; as origens preservadas não são apagadas.</p><form method="get" action="<?= $esc($url); ?>"><label>Número do lote<input name="origin" inputmode="numeric" pattern="[1-9][0-9]*" required></label><button type="submit">Consultar lote histórico</button></form><ul><?php foreach($choices['batches'] as $batch){ ?><li><a href="<?= $esc($url.'?origin='.(int)$batch['origin_id']); ?>">Lote #<?= (int)$batch['origin_id']; ?> · <?= $esc($batch['state']); ?></a></li><?php } ?></ul><?php } ?></section><?php require APPPATH.'views/admin/includes/native_company_layout_tail.php'; ?>
